insert into public.content_sources (key, open5e_key, title, publisher, license_keys, copyright_notice, product_url, gamesystem, is_redistributable, is_metadata_curated, sort_order)
insert into public.library_species (id, name, description, size, speed, ability_score_increases, traits, languages, tags, subraces, is_shapeshifter, source, source_title, ruleset, conceptual_key, source_document_key, source_record_key, source_revision, source_license, provenance)
values
  ('grimoire_goblin', 'Goblin', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Goblins are quick, sharp-eared folk who build their towns in the cracks other people ignore: ravine walls, old mines, the undercroft of a bridge. They live loudly and close together, trade in anything that can be carried, and judge a neighbour by how well they share a find."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Most stand a little over three feet tall, with long pointed ears, sharp noses and skin in shades of moss, olive and ochre. An outsider sees chaos in a goblin market; a goblin sees a hundred arguments being settled at once."}]}]}', 'small', '{"walk": 30}'::jsonb, '{"dex": 2, "con": 1}'::jsonb, '[{"name": "Darkvision", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You discern colours in that darkness only as shades of grey.\"}]}]}"}, {"name": "Clear Head", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws you make to avoid or end the Charmed condition.\"}]}]}"}, {"name": "Punch Above Your Weight", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you deal damage to a creature larger than you with an attack or a spell, you can deal extra damage to it equal to your Proficiency Bonus. You can do this a number of times equal to your Proficiency Bonus, no more than once per turn, and you regain all uses when you finish a Long Rest.\"}]}]}"}, {"name": "Duck and Run", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can take the Disengage or Hide action as a Bonus Action on each of your turns.\"}]}]}"}]'::jsonb, array['Common', 'Goblin']::text[], array['humanoid', 'small', 'goblin']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'goblin', 'grimoire-species', 'grimoire_2014_goblin', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_goblin', 'Goblin', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Goblins are quick, sharp-eared folk who build their towns in the cracks other people ignore: ravine walls, old mines, the undercroft of a bridge. They live loudly and close together, trade in anything that can be carried, and judge a neighbour by how well they share a find."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Most stand a little over three feet tall, with long pointed ears, sharp noses and skin in shades of moss, olive and ochre. An outsider sees chaos in a goblin market; a goblin sees a hundred arguments being settled at once."}]}]}', 'small', '{"walk": 30}'::jsonb, null, '[{"name": "Darkvision", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You discern colours in that darkness only as shades of grey.\"}]}]}"}, {"name": "Clear Head", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws you make to avoid or end the Charmed condition.\"}]}]}"}, {"name": "Punch Above Your Weight", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you deal damage to a creature larger than you with an attack or a spell, you can deal extra damage to it equal to your Proficiency Bonus. You can do this a number of times equal to your Proficiency Bonus, no more than once per turn, and you regain all uses when you finish a Long Rest.\"}]}]}"}, {"name": "Duck and Run", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can take the Disengage or Hide action as a Bonus Action on each of your turns.\"}]}]}"}]'::jsonb, array['Common', 'Goblin']::text[], array['humanoid', 'small', 'goblin']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'goblin', 'grimoire-species', 'grimoire_2024_goblin', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_kobold', 'Kobold', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kobolds are small, scaled people who carry an old, proud certainty that dragons are their kin. They dig deep, build cleverly and look after one another fiercely; a kobold warren is a maze of tunnels, traps and workshops, and every member has a craft."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They stand two and a half to three feet tall, with snouts, small horns and tails, and scales in rust, copper, ochre and slate. Their voices are high and carrying, and a kobold who shouts at an enemy is rarely shouting alone."}]}]}', 'small', '{"walk": 30}'::jsonb, '{"dex": 2, "int": 1}'::jsonb, '[{"name": "Darkvision", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You discern colours in that darkness only as shades of grey.\"}]}]}"}, {"name": "Rallying Shriek", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Bonus Action, you let out a piercing cry at enemies within 10 feet of you. Until the start of your next turn, you and your allies have Advantage on attack rolls against any of those enemies who could hear you. You can do this a number of times equal to your Proficiency Bonus, and you regain all uses when you finish a Long Rest.\"}]}]}"}, {"name": "Wyrmkin Gift", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Choose one of the following when you pick this species. Warren-Taught: you gain proficiency in one of these skills: Arcana, Investigation, Medicine, Sleight of Hand or Survival. Hard Scales: you have Advantage on saving throws you make to avoid or end the Frightened condition. Spark of the Wyrm: you know one cantrip of your choice from the Sorcerer spell list; Intelligence, Wisdom or Charisma is your spellcasting ability for it (choose when you select this option).\"}]}]}"}]'::jsonb, array['Common', 'Draconic']::text[], array['humanoid', 'small', 'kobold']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'kobold', 'grimoire-species', 'grimoire_2014_kobold', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_kobold', 'Kobold', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kobolds are small, scaled people who carry an old, proud certainty that dragons are their kin. They dig deep, build cleverly and look after one another fiercely; a kobold warren is a maze of tunnels, traps and workshops, and every member has a craft."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They stand two and a half to three feet tall, with snouts, small horns and tails, and scales in rust, copper, ochre and slate. Their voices are high and carrying, and a kobold who shouts at an enemy is rarely shouting alone."}]}]}', 'small', '{"walk": 30}'::jsonb, null, '[{"name": "Darkvision", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You discern colours in that darkness only as shades of grey.\"}]}]}"}, {"name": "Rallying Shriek", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Bonus Action, you let out a piercing cry at enemies within 10 feet of you. Until the start of your next turn, you and your allies have Advantage on attack rolls against any of those enemies who could hear you. You can do this a number of times equal to your Proficiency Bonus, and you regain all uses when you finish a Long Rest.\"}]}]}"}, {"name": "Wyrmkin Gift", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Choose one of the following when you pick this species. Warren-Taught: you gain proficiency in one of these skills: Arcana, Investigation, Medicine, Sleight of Hand or Survival. Hard Scales: you have Advantage on saving throws you make to avoid or end the Frightened condition. Spark of the Wyrm: you know one cantrip of your choice from the Sorcerer spell list; Intelligence, Wisdom or Charisma is your spellcasting ability for it (choose when you select this option).\"}]}]}"}]'::jsonb, array['Common', 'Draconic']::text[], array['humanoid', 'small', 'kobold']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'kobold', 'grimoire-species', 'grimoire_2024_kobold', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_aasimar', 'Aasimar', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Aasimar are people whose bloodline carries a spark from the celestial planes. Their eyes glow softly like lamps behind frosted glass, their hair shines like brushed brass or silver, and a faint warmth seems to follow them into cold rooms."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Most are born into ordinary families and grow up feeling watched over by something they cannot name. Some answer that feeling by becoming healers and guards, others spend their lives resisting the pull. Wings appear only when their inner light flares, and they fade with it."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"cha": 2, "wis": 1}'::jsonb, '[{"name": "Dusk Sight", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Gravebane Blood", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to necrotic damage and to radiant damage.\"}]}]}"}, {"name": "Lantern Touch", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You know the Light cantrip. Charisma is your spellcasting ability for it.\"}]}]}"}, {"name": "Mending Palm", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Magic action, you touch a creature and restore a number of Hit Points equal to your Proficiency Bonus rolled as d4s, adding the dice together. Once used, you cannot do this again until you finish a Long Rest.\"}]}]}"}, {"name": "Radiant Awakening", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Bonus action, you unleash your inner glow for 1 minute. Once used, you cannot do this again until you finish a Long Rest. When you awaken, choose one form. Shining Pinions: spectral wings grant you a Fly speed equal to your Speed. Burning Halo: you shed bright light in a 10-foot radius and dim light for another 10 feet, and at the end of each of your turns every creature within 10 feet takes radiant damage equal to your Proficiency Bonus. Grave Mantle: creatures of your choice within 10 feet that can see you must succeed on a Charisma saving throw (DC 8 + your Charisma modifier + your Proficiency Bonus) or have the Frightened condition until the end of your next turn. Once on each of your turns while awakened, one attack or spell of yours deals extra damage of the same type equal to your Proficiency Bonus.\"}]}]}"}]'::jsonb, array['Common', 'Celestial']::text[], array['humanoid', 'medium', 'aasimar']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'aasimar', 'grimoire-species', 'grimoire_2014_aasimar', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_aasimar', 'Aasimar', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Aasimar are people whose bloodline carries a spark from the celestial planes. Their eyes glow softly like lamps behind frosted glass, their hair shines like brushed brass or silver, and a faint warmth seems to follow them into cold rooms."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Most are born into ordinary families and grow up feeling watched over by something they cannot name. Some answer that feeling by becoming healers and guards, others spend their lives resisting the pull. Wings appear only when their inner light flares, and they fade with it."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Dusk Sight", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Gravebane Blood", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to necrotic damage and to radiant damage.\"}]}]}"}, {"name": "Lantern Touch", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You know the Light cantrip. Charisma is your spellcasting ability for it.\"}]}]}"}, {"name": "Mending Palm", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Magic action, you touch a creature and restore a number of Hit Points equal to your Proficiency Bonus rolled as d4s, adding the dice together. Once used, you cannot do this again until you finish a Long Rest.\"}]}]}"}, {"name": "Radiant Awakening", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Bonus action, you unleash your inner glow for 1 minute. Once used, you cannot do this again until you finish a Long Rest. When you awaken, choose one form. Shining Pinions: spectral wings grant you a Fly speed equal to your Speed. Burning Halo: you shed bright light in a 10-foot radius and dim light for another 10 feet, and at the end of each of your turns every creature within 10 feet takes radiant damage equal to your Proficiency Bonus. Grave Mantle: creatures of your choice within 10 feet that can see you must succeed on a Charisma saving throw (DC 8 + your Charisma modifier + your Proficiency Bonus) or have the Frightened condition until the end of your next turn. Once on each of your turns while awakened, one attack or spell of yours deals extra damage of the same type equal to your Proficiency Bonus.\"}]}]}"}]'::jsonb, array['Common', 'Celestial']::text[], array['humanoid', 'medium', 'aasimar']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'aasimar', 'grimoire-species', 'grimoire_2024_aasimar', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_changeling', 'Changeling', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Changelings have pale grey skin, eyes with no colour in them, and faces that look slightly unfinished, as if a sculptor stopped before the last touches. They can reshape those faces at will, and most spend their lives in crowded cities where one more stranger draws no stares."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Because the world is wary of what they are, many keep a handful of borrowed identities and a plain one they show to nobody. Close friends learn to ask a question only the real person would answer. A changeling who shows you their true face has decided to trust you."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"cha": 2, "dex": 1}'::jsonb, '[{"name": "Practised Liar", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You gain proficiency in two of these skills of your choice: Deception, Insight, Intimidation, Performance or Persuasion.\"}]}]}"}, {"name": "Face Loom", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Magic action, you reshape your face, hair, voice and body into those of another Small or Medium humanoid, adding or removing up to a foot of height. Your gear does not change. You can use any look you have seen, or invent one. The change lasts until you use the action again, return to your true shape, or die. Physical inspection will not expose it, but a creature that studies you can make an Intelligence (Investigation) check against your Deception to spot oddities in your behaviour.\"}]}]}"}]'::jsonb, array['Common', 'Elvish']::text[], array['humanoid', 'medium', 'changeling']::text[], null, true, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'changeling', 'grimoire-species', 'grimoire_2014_changeling', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_changeling', 'Changeling', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Changelings have pale grey skin, eyes with no colour in them, and faces that look slightly unfinished, as if a sculptor stopped before the last touches. They can reshape those faces at will, and most spend their lives in crowded cities where one more stranger draws no stares."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Because the world is wary of what they are, many keep a handful of borrowed identities and a plain one they show to nobody. Close friends learn to ask a question only the real person would answer. A changeling who shows you their true face has decided to trust you."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Practised Liar", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You gain proficiency in two of these skills of your choice: Deception, Insight, Intimidation, Performance or Persuasion.\"}]}]}"}, {"name": "Face Loom", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Magic action, you reshape your face, hair, voice and body into those of another Small or Medium humanoid, adding or removing up to a foot of height. Your gear does not change. You can use any look you have seen, or invent one. The change lasts until you use the action again, return to your true shape, or die. Physical inspection will not expose it, but a creature that studies you can make an Intelligence (Investigation) check against your Deception to spot oddities in your behaviour.\"}]}]}"}]'::jsonb, array['Common', 'Elvish']::text[], array['humanoid', 'medium', 'changeling']::text[], null, true, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'changeling', 'grimoire-species', 'grimoire_2024_changeling', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_shifter', 'Shifter', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Shifters carry something of the wild in their blood. Bear, wolf, fox or cat, the beast shows through in the heavy brow, the pointed ears, the slit eyes, the thick hair on forearms and neck. They are broad-shouldered, restless, and rarely at ease behind walls."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "When they call the animal forward, those traits sharpen: fangs lengthen, muscles bunch, senses narrow to the hunt. Many shifter clans keep to the edge of towns, trading furs and guide work, and judge strangers on how they treat animals and children."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"dex": 2, "wis": 1}'::jsonb, '[{"name": "Night Eyes", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Wary Senses", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have proficiency in the Perception skill.\"}]}]}"}, {"name": "Wild Surge", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Bonus action, you bring the beast to the surface for 1 minute. You can use this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest. When you surge, you gain Temporary Hit Points equal to twice your Proficiency Bonus, and you choose an aspect that lasts for the duration. Bear Aspect: your Armour Class increases by 1. Wolf Aspect: you can make an unarmed bite as part of the Attack action, dealing 1d6 piercing damage plus your Strength modifier. Fox Aspect: your Speed increases by 10 feet. Cat Aspect: you gain a Climb speed of 30 feet and Advantage on Wisdom (Perception) checks.\"}]}]}"}]'::jsonb, array['Common', 'Elvish']::text[], array['humanoid', 'medium', 'shifter']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'shifter', 'grimoire-species', 'grimoire_2014_shifter', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_shifter', 'Shifter', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Shifters carry something of the wild in their blood. Bear, wolf, fox or cat, the beast shows through in the heavy brow, the pointed ears, the slit eyes, the thick hair on forearms and neck. They are broad-shouldered, restless, and rarely at ease behind walls."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "When they call the animal forward, those traits sharpen: fangs lengthen, muscles bunch, senses narrow to the hunt. Many shifter clans keep to the edge of towns, trading furs and guide work, and judge strangers on how they treat animals and children."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Night Eyes", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Wary Senses", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have proficiency in the Perception skill.\"}]}]}"}, {"name": "Wild Surge", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Bonus action, you bring the beast to the surface for 1 minute. You can use this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest. When you surge, you gain Temporary Hit Points equal to twice your Proficiency Bonus, and you choose an aspect that lasts for the duration. Bear Aspect: your Armour Class increases by 1. Wolf Aspect: you can make an unarmed bite as part of the Attack action, dealing 1d6 piercing damage plus your Strength modifier. Fox Aspect: your Speed increases by 10 feet. Cat Aspect: you gain a Climb speed of 30 feet and Advantage on Wisdom (Perception) checks.\"}]}]}"}]'::jsonb, array['Common', 'Elvish']::text[], array['humanoid', 'medium', 'shifter']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'shifter', 'grimoire-species', 'grimoire_2024_shifter', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_loxodon', 'Loxodon', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Loxodons are tall, grey-skinned people with an elephant''s head: wide fan ears, ivory tusks and a long, dexterous trunk. They tend to settle beside slow rivers, where whole districts are built around shared courtyards and long evening talks."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They speak softly and rarely hurry, and their memory for faces and promises is famously good. A loxodon will wait out an argument rather than win it. Anger comes late, but the elders say it is very hard to put down once it arrives."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"con": 2, "wis": 1}'::jsonb, '[{"name": "Heavy Frame", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You count as one size larger when determining your carrying capacity and the weight you can push, drag or lift.\"}]}]}"}, {"name": "Thick Hide", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you are not wearing armour, your Armour Class is 12 plus your Constitution modifier. You can use a shield and still gain this benefit.\"}]}]}"}, {"name": "Tranquil Mind", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws against the Charmed and Frightened conditions.\"}]}]}"}, {"name": "Grasping Snout", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your trunk can pick up, hold and carry an object of up to 10 pounds, open or close doors and containers, and do other simple manipulation. It cannot wield weapons or shields, or perform tasks needing fine precision.\"}]}]}"}, {"name": "Scent Reader", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on Wisdom (Perception) and Wisdom (Survival) checks that rely on smell.\"}]}]}"}]'::jsonb, array['Common', 'Giant']::text[], array['humanoid', 'medium', 'loxodon']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'loxodon', 'grimoire-species', 'grimoire_2014_loxodon', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_loxodon', 'Loxodon', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Loxodons are tall, grey-skinned people with an elephant''s head: wide fan ears, ivory tusks and a long, dexterous trunk. They tend to settle beside slow rivers, where whole districts are built around shared courtyards and long evening talks."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They speak softly and rarely hurry, and their memory for faces and promises is famously good. A loxodon will wait out an argument rather than win it. Anger comes late, but the elders say it is very hard to put down once it arrives."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Heavy Frame", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You count as one size larger when determining your carrying capacity and the weight you can push, drag or lift.\"}]}]}"}, {"name": "Thick Hide", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you are not wearing armour, your Armour Class is 12 plus your Constitution modifier. You can use a shield and still gain this benefit.\"}]}]}"}, {"name": "Tranquil Mind", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws against the Charmed and Frightened conditions.\"}]}]}"}, {"name": "Grasping Snout", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your trunk can pick up, hold and carry an object of up to 10 pounds, open or close doors and containers, and do other simple manipulation. It cannot wield weapons or shields, or perform tasks needing fine precision.\"}]}]}"}, {"name": "Scent Reader", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on Wisdom (Perception) and Wisdom (Survival) checks that rely on smell.\"}]}]}"}]'::jsonb, array['Common', 'Giant']::text[], array['humanoid', 'medium', 'loxodon']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'loxodon', 'grimoire-species', 'grimoire_2024_loxodon', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_firbolg', 'Firbolg', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Firbolgs are gentle forest dwellers with blue-grey skin, long drooping ears and a height that makes doorways an afterthought. They live in hidden groves and tend them like gardens, and they have no great wish to be found."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Their quiet manner hides a stubborn streak: harm a tree in their grove and you will find yourself politely, repeatedly lost. They greet travellers with food and say little, and what they say tends to be exactly what they mean."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"wis": 2, "str": 1}'::jsonb, '[{"name": "Grove Craft", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can cast Detect Magic and Disguise Self. Each works once per Long Rest, and Wisdom is your spellcasting ability for them. When you cast Disguise Self with this trait, you can appear up to 3 feet shorter.\"}]}]}"}, {"name": "Vanishing Footstep", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Bonus action, you turn invisible until the start of your next turn, or until you attack or deal damage. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}, {"name": "Tongue of Branch and Beast", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can communicate simple ideas to beasts and plants by speaking and gesturing, and you can understand the broad meaning of their sounds and movements.\"}]}]}"}, {"name": "Giant''s Heft", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You count as one size larger when determining your carrying capacity and the weight you can push, drag or lift.\"}]}]}"}]'::jsonb, array['Common', 'Giant']::text[], array['humanoid', 'medium', 'firbolg']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'firbolg', 'grimoire-species', 'grimoire_2014_firbolg', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_firbolg', 'Firbolg', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Firbolgs are gentle forest dwellers with blue-grey skin, long drooping ears and a height that makes doorways an afterthought. They live in hidden groves and tend them like gardens, and they have no great wish to be found."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Their quiet manner hides a stubborn streak: harm a tree in their grove and you will find yourself politely, repeatedly lost. They greet travellers with food and say little, and what they say tends to be exactly what they mean."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Grove Craft", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can cast Detect Magic and Disguise Self. Each works once per Long Rest, and Wisdom is your spellcasting ability for them. When you cast Disguise Self with this trait, you can appear up to 3 feet shorter.\"}]}]}"}, {"name": "Vanishing Footstep", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Bonus action, you turn invisible until the start of your next turn, or until you attack or deal damage. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}, {"name": "Tongue of Branch and Beast", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can communicate simple ideas to beasts and plants by speaking and gesturing, and you can understand the broad meaning of their sounds and movements.\"}]}]}"}, {"name": "Giant''s Heft", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You count as one size larger when determining your carrying capacity and the weight you can push, drag or lift.\"}]}]}"}]'::jsonb, array['Common', 'Giant']::text[], array['humanoid', 'medium', 'firbolg']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'firbolg', 'grimoire-species', 'grimoire_2024_firbolg', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_elementborn', 'Elementborn', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Elementborn are people whose ancestry was touched by a force older than the gods: flame, stone, tide or gale. The touch shows in the skin and hair, which may glow, grow rough like rock, ripple like water, or drift as though in a breeze."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Some are raised to be proud of it and some are kept at arm''s length by neighbours. Wherever they settle, they gravitate to places where their element is strong, and they learn early that they cannot hide what they are."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"con": 2}'::jsonb, '[{"name": "Elemental Bloodline", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Choose one of the four lineages below. It gives you a resistance, a few spells and a special ability. Charisma, Intelligence or Wisdom (pick one when you choose) is your spellcasting ability for the spells it grants.\"}]}]}"}]'::jsonb, array['Common', 'Primordial']::text[], array['humanoid', 'medium', 'elementborn']::text[], '[{"name": "Fire", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Embers glow in your eyes and your skin runs hot to the touch.\"}]}]}", "traits": [{"name": "Ember Sight", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Cinder Hide", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to fire damage.\"}]}]}"}, {"name": "Spark of the Hearth", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You know the Produce Flame cantrip. At 3rd level, you can cast Burning Hands once per Long Rest.\"}]}]}"}]}, {"name": "Earth", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your skin carries the grain of stone and your steps feel unmoved by the ground.\"}]}]}", "traits": [{"name": "Stone Stride", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You ignore Difficult Terrain made of earth or stone.\"}]}]}"}, {"name": "Quiet Rock", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can cast Pass Without Trace once per Long Rest, starting at 3rd level.\"}]}]}"}, {"name": "Mountain Bones", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to bludgeoning damage from nonmagical sources.\"}]}]}"}]}, {"name": "Water", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your hair and skin shimmer with a faint wet sheen, and you feel at home near any tide.\"}]}]}", "traits": [{"name": "Gill Lungs", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can breathe air and water.\"}]}]}"}, {"name": "Current Swimmer", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have a Swim speed of 30 feet.\"}]}]}"}, {"name": "Brine Spray", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to acid damage and know the Acid Splash cantrip. At 3rd level, you can cast Create or Destroy Water once per Long Rest.\"}]}]}"}]}, {"name": "Air", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your hair stirs without a breeze and breath comes to you easily, even where little air is to be had.\"}]}]}", "traits": [{"name": "Endless Breath", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can hold your breath indefinitely while you are not Incapacitated.\"}]}]}"}, {"name": "Storm Veins", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to lightning damage and know the Shocking Grasp cantrip.\"}]}]}"}, {"name": "Gale Step", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"At 3rd level, you can cast Levitate once per Long Rest.\"}]}]}"}]}]'::jsonb, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'elementborn', 'grimoire-species', 'grimoire_2014_elementborn', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_elementborn', 'Elementborn', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Elementborn are people whose ancestry was touched by a force older than the gods: flame, stone, tide or gale. The touch shows in the skin and hair, which may glow, grow rough like rock, ripple like water, or drift as though in a breeze."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Some are raised to be proud of it and some are kept at arm''s length by neighbours. Wherever they settle, they gravitate to places where their element is strong, and they learn early that they cannot hide what they are."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Elemental Bloodline", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Choose one of the four lineages below. It gives you a resistance, a few spells and a special ability. Charisma, Intelligence or Wisdom (pick one when you choose) is your spellcasting ability for the spells it grants.\"}]}]}"}]'::jsonb, array['Common', 'Primordial']::text[], array['humanoid', 'medium', 'elementborn']::text[], '[{"name": "Fire", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Embers glow in your eyes and your skin runs hot to the touch.\"}]}]}", "traits": [{"name": "Ember Sight", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Cinder Hide", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to fire damage.\"}]}]}"}, {"name": "Spark of the Hearth", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You know the Produce Flame cantrip. At 3rd level, you can cast Burning Hands once per Long Rest.\"}]}]}"}]}, {"name": "Earth", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your skin carries the grain of stone and your steps feel unmoved by the ground.\"}]}]}", "traits": [{"name": "Stone Stride", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You ignore Difficult Terrain made of earth or stone.\"}]}]}"}, {"name": "Quiet Rock", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can cast Pass Without Trace once per Long Rest, starting at 3rd level.\"}]}]}"}, {"name": "Mountain Bones", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to bludgeoning damage from nonmagical sources.\"}]}]}"}]}, {"name": "Water", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your hair and skin shimmer with a faint wet sheen, and you feel at home near any tide.\"}]}]}", "traits": [{"name": "Gill Lungs", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can breathe air and water.\"}]}]}"}, {"name": "Current Swimmer", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have a Swim speed of 30 feet.\"}]}]}"}, {"name": "Brine Spray", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to acid damage and know the Acid Splash cantrip. At 3rd level, you can cast Create or Destroy Water once per Long Rest.\"}]}]}"}]}, {"name": "Air", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your hair stirs without a breeze and breath comes to you easily, even where little air is to be had.\"}]}]}", "traits": [{"name": "Endless Breath", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can hold your breath indefinitely while you are not Incapacitated.\"}]}]}"}, {"name": "Storm Veins", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to lightning damage and know the Shocking Grasp cantrip.\"}]}]}"}, {"name": "Gale Step", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"At 3rd level, you can cast Levitate once per Long Rest.\"}]}]}"}]}]'::jsonb, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'elementborn', 'grimoire-species', 'grimoire_2024_elementborn', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_hexborn', 'Hexborn', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hexborn are people whom a hag''s bargain or a hag''s blood has altered. Living twigs curl through their hair like a crown, their eyes sit slightly wrong, and their shadows are sometimes a beat late. The tales told about them have a nasty edge."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They are raised either in a coven''s care or in exile from it, and learn to read the bargains hiding in every kind word. A hexborn who keeps their word is rare and loyal for life; the ones who do not become the tales."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"con": 2, "cha": 1}'::jsonb, '[{"name": "Gloaming Vision", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Wicked Blood", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws against the Charmed condition.\"}]}]}"}, {"name": "Crone''s Craft", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can cast Disguise Self and Hex, each once per Long Rest without a spell slot. You can also cast them using spell slots of the right level. Charisma is your spellcasting ability for them.\"}]}]}"}, {"name": "Lock of Hair", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Magic action, you give a creature a lock of your hair, a nail clipping or a twig. For 1 hour, you can use a Bonus action to speak a short message that only the holder hears, from any distance on the same plane, and you can hear their reply. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}]'::jsonb, array['Common', 'Sylvan']::text[], array['humanoid', 'medium', 'hexborn']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'hexborn', 'grimoire-species', 'grimoire_2014_hexborn', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_hexborn', 'Hexborn', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hexborn are people whom a hag''s bargain or a hag''s blood has altered. Living twigs curl through their hair like a crown, their eyes sit slightly wrong, and their shadows are sometimes a beat late. The tales told about them have a nasty edge."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They are raised either in a coven''s care or in exile from it, and learn to read the bargains hiding in every kind word. A hexborn who keeps their word is rare and loyal for life; the ones who do not become the tales."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Gloaming Vision", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Wicked Blood", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws against the Charmed condition.\"}]}]}"}, {"name": "Crone''s Craft", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can cast Disguise Self and Hex, each once per Long Rest without a spell slot. You can also cast them using spell slots of the right level. Charisma is your spellcasting ability for them.\"}]}]}"}, {"name": "Lock of Hair", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Magic action, you give a creature a lock of your hair, a nail clipping or a twig. For 1 hour, you can use a Bonus action to speak a short message that only the holder hears, from any distance on the same plane, and you can hear their reply. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}]'::jsonb, array['Common', 'Sylvan']::text[], array['humanoid', 'medium', 'hexborn']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'hexborn', 'grimoire-species', 'grimoire_2024_hexborn', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_shellfolk', 'Shellfolk', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Shellfolk walk upright under a domed shell patterned in browns and greens, with thick-skinned limbs, a horn-edged beak and calm, heavy-lidded eyes. They build villages of woven reed and driftwood on warm coasts, close to the shore and farther from trouble."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They are famously unhurried, and plenty of travellers mistake that for slowness. A shellfolk who finally speaks has usually made up their mind. When something goes wrong they simply fold into their shell and wait for the matter to come to its senses."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"str": 2, "wis": 1}'::jsonb, '[{"name": "Claw Strike", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your hands are sharp claws. Your unarmed strikes deal 1d6 slashing damage plus your Strength modifier.\"}]}]}"}, {"name": "Deep Lungs", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can hold your breath for up to 1 hour.\"}]}]}"}, {"name": "Carapace", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your shell gives you a base Armour Class of 17, which ignores your Dexterity modifier. You cannot wear armour to improve this, but you can use a shield.\"}]}]}"}, {"name": "Draw In", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Magic action, you pull your head and limbs into your shell. While drawn in, you gain a +4 bonus to Armour Class and Advantage on Strength and Constitution saving throws, but you have the Prone condition, your Speed is 0, you have Disadvantage on Dexterity saving throws, you cannot take Reactions, and the only action you can take is a Bonus action to emerge.\"}]}]}"}, {"name": "Shore Lore", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have proficiency in the Survival skill.\"}]}]}"}]'::jsonb, array['Common', 'Primordial']::text[], array['humanoid', 'medium', 'shellfolk']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'shellfolk', 'grimoire-species', 'grimoire_2014_shellfolk', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_shellfolk', 'Shellfolk', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Shellfolk walk upright under a domed shell patterned in browns and greens, with thick-skinned limbs, a horn-edged beak and calm, heavy-lidded eyes. They build villages of woven reed and driftwood on warm coasts, close to the shore and farther from trouble."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They are famously unhurried, and plenty of travellers mistake that for slowness. A shellfolk who finally speaks has usually made up their mind. When something goes wrong they simply fold into their shell and wait for the matter to come to its senses."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Claw Strike", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your hands are sharp claws. Your unarmed strikes deal 1d6 slashing damage plus your Strength modifier.\"}]}]}"}, {"name": "Deep Lungs", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can hold your breath for up to 1 hour.\"}]}]}"}, {"name": "Carapace", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your shell gives you a base Armour Class of 17, which ignores your Dexterity modifier. You cannot wear armour to improve this, but you can use a shield.\"}]}]}"}, {"name": "Draw In", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Magic action, you pull your head and limbs into your shell. While drawn in, you gain a +4 bonus to Armour Class and Advantage on Strength and Constitution saving throws, but you have the Prone condition, your Speed is 0, you have Disadvantage on Dexterity saving throws, you cannot take Reactions, and the only action you can take is a Bonus action to emerge.\"}]}]}"}, {"name": "Shore Lore", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have proficiency in the Survival skill.\"}]}]}"}]'::jsonb, array['Common', 'Primordial']::text[], array['humanoid', 'medium', 'shellfolk']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'shellfolk', 'grimoire-species', 'grimoire_2024_shellfolk', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_hobgoblin', 'Hobgoblin', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hobgoblins are tall, lean and red-orange, with narrow eyes and broad flat smiles that rarely reach them. They raise their young in walled citadels where rank, drill and obligation are the whole of civic life, and where a debt is remembered across generations."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Away from the legion, hobgoblins are formidable, disciplined travellers who treat a good plan as a point of honour. They give help freely and expect it returned, and they hold a grudge exactly as long as the debt is owed."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"con": 2, "int": 1}'::jsonb, '[{"name": "Barracks Sight", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Unbent Mind", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws against the Charmed condition.\"}]}]}"}, {"name": "Drilled Assistance", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Bonus action, you can take the Help action, with a range of 30 feet for the aid. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}, {"name": "Rallying Luck", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you or an ally you can see within 30 feet misses with an attack, or fails an ability check or saving throw, you can add 2d4 to that d20 roll as a Reaction, potentially turning failure into success. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}]'::jsonb, array['Common', 'Goblin']::text[], array['humanoid', 'medium', 'hobgoblin']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'hobgoblin', 'grimoire-species', 'grimoire_2014_hobgoblin', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_hobgoblin', 'Hobgoblin', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hobgoblins are tall, lean and red-orange, with narrow eyes and broad flat smiles that rarely reach them. They raise their young in walled citadels where rank, drill and obligation are the whole of civic life, and where a debt is remembered across generations."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Away from the legion, hobgoblins are formidable, disciplined travellers who treat a good plan as a point of honour. They give help freely and expect it returned, and they hold a grudge exactly as long as the debt is owed."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Barracks Sight", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Unbent Mind", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws against the Charmed condition.\"}]}]}"}, {"name": "Drilled Assistance", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Bonus action, you can take the Help action, with a range of 30 feet for the aid. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}, {"name": "Rallying Luck", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you or an ally you can see within 30 feet misses with an attack, or fails an ability check or saving throw, you can add 2d4 to that d20 roll as a Reaction, potentially turning failure into success. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}]'::jsonb, array['Common', 'Goblin']::text[], array['humanoid', 'medium', 'hobgoblin']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'hobgoblin', 'grimoire-species', 'grimoire_2024_hobgoblin', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_bugbear', 'Bugbear', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bugbears are huge, shaggy goblinoids whose arms hang nearly to their knees. Coarse fur ranges from tawny to near black, and their eyes pick out shapes in deep shade. They favour tangled woods and shadowed ridges."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "For all that bulk, they move with unnerving quiet. A bugbear camp often goes unseen until the travellers are inside it, and the old tales of them dropping out of the dark are mostly true. They are patient hunters who find loud confrontation undignified."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"str": 2, "dex": 1}'::jsonb, '[{"name": "Shadow Sight", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Reaching Arms", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you make a melee attack on your turn, your reach for it is 5 feet greater than normal.\"}]}]}"}, {"name": "Broad Frame", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You count as one size larger when determining your carrying capacity and the weight you can push, drag or lift.\"}]}]}"}, {"name": "Soft Tread", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have proficiency in the Stealth skill.\"}]}]}"}, {"name": "Ambush Blow", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"If you hit a creature that has not taken a turn in the current combat, you deal an extra 2d6 damage to it on that hit. You can do this once per combat.\"}]}]}"}]'::jsonb, array['Common', 'Goblin']::text[], array['humanoid', 'medium', 'bugbear']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'bugbear', 'grimoire-species', 'grimoire_2014_bugbear', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_bugbear', 'Bugbear', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bugbears are huge, shaggy goblinoids whose arms hang nearly to their knees. Coarse fur ranges from tawny to near black, and their eyes pick out shapes in deep shade. They favour tangled woods and shadowed ridges."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "For all that bulk, they move with unnerving quiet. A bugbear camp often goes unseen until the travellers are inside it, and the old tales of them dropping out of the dark are mostly true. They are patient hunters who find loud confrontation undignified."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Shadow Sight", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Reaching Arms", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you make a melee attack on your turn, your reach for it is 5 feet greater than normal.\"}]}]}"}, {"name": "Broad Frame", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You count as one size larger when determining your carrying capacity and the weight you can push, drag or lift.\"}]}]}"}, {"name": "Soft Tread", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have proficiency in the Stealth skill.\"}]}]}"}, {"name": "Ambush Blow", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"If you hit a creature that has not taken a turn in the current combat, you deal an extra 2d6 damage to it on that hit. You can do this once per combat.\"}]}]}"}]'::jsonb, array['Common', 'Goblin']::text[], array['humanoid', 'medium', 'bugbear']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'bugbear', 'grimoire-species', 'grimoire_2024_bugbear', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_birdfolk', 'Birdfolk', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Birdfolk are slender, feathered people with hooked beaks, sharp eyes and broad wings folded along their backs. They build nests in high cliffs and tower tops, reached by ledges and rope ladders that few outsiders would trust."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Wind is their calendar and their language: they read weather in feather-tips and speak in whistles and trills. The ground feels cramped to them, and most of their stories begin or end with a fall. Many are curious wanderers by nature."}]}]}', 'medium', '{"walk": 30, "fly": 30}'::jsonb, '{"dex": 2, "wis": 1}'::jsonb, '[{"name": "Feathered Wings", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have a Fly speed of 30 feet. You cannot fly while wearing medium or heavy armour.\"}]}]}"}, {"name": "Hooked Claws", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your fingers end in claws. Your unarmed strikes deal 1d4 slashing damage plus your Strength modifier.\"}]}]}"}, {"name": "Squall Whistle", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can cast Gust of Wind once per Long Rest, starting at 3rd level, without a spell slot. Wisdom is your spellcasting ability for it.\"}]}]}"}]'::jsonb, array['Common', 'Primordial']::text[], array['humanoid', 'medium', 'birdfolk']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'birdfolk', 'grimoire-species', 'grimoire_2014_birdfolk', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_birdfolk', 'Birdfolk', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Birdfolk are slender, feathered people with hooked beaks, sharp eyes and broad wings folded along their backs. They build nests in high cliffs and tower tops, reached by ledges and rope ladders that few outsiders would trust."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Wind is their calendar and their language: they read weather in feather-tips and speak in whistles and trills. The ground feels cramped to them, and most of their stories begin or end with a fall. Many are curious wanderers by nature."}]}]}', 'medium', '{"walk": 30, "fly": 30}'::jsonb, null, '[{"name": "Feathered Wings", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have a Fly speed of 30 feet. You cannot fly while wearing medium or heavy armour.\"}]}]}"}, {"name": "Hooked Claws", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your fingers end in claws. Your unarmed strikes deal 1d4 slashing damage plus your Strength modifier.\"}]}]}"}, {"name": "Squall Whistle", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can cast Gust of Wind once per Long Rest, starting at 3rd level, without a spell slot. Wisdom is your spellcasting ability for it.\"}]}]}"}]'::jsonb, array['Common', 'Primordial']::text[], array['humanoid', 'medium', 'birdfolk']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'birdfolk', 'grimoire-species', 'grimoire_2024_birdfolk', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_corvid-folk', 'Corvid Folk', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Corvid folk have black feathers, sharp dark eyes and hooked, glossy beaks. Their wings were lost long ago, and they now live on old rooftops, in belfries and chimney-stacks, where they collect scraps, secrets and shiny things."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Their own voices are thin and rasping, so they speak the world in borrowed sounds: a door creak, a laugh, a merchant''s cry. A corvid who has heard you once can speak in your voice for years, and the clever ones know exactly why that is useful."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"dex": 2, "wis": 1}'::jsonb, '[{"name": "Careful Hand", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on any check you make to copy handwriting or a crafted object that you have seen.\"}]}]}"}, {"name": "Rooftop Training", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You gain proficiency in two of these skills of your choice: Acrobatics, Deception, Stealth or Sleight of Hand.\"}]}]}"}, {"name": "Borrowed Voices", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can reproduce sounds you have heard, including voices. A creature that hears the sounds you make can tell they are imitations with a successful Wisdom (Insight) check against your Charisma (Deception) check.\"}]}]}"}, {"name": "Perfect Recollection", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you make an Intelligence check to recall something you have heard or seen, you can treat a roll of 9 or lower on the d20 as a 10.\"}]}]}"}]'::jsonb, array['Common', 'Primordial']::text[], array['humanoid', 'medium', 'corvid-folk']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'corvid-folk', 'grimoire-species', 'grimoire_2014_corvid-folk', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_corvid-folk', 'Corvid Folk', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Corvid folk have black feathers, sharp dark eyes and hooked, glossy beaks. Their wings were lost long ago, and they now live on old rooftops, in belfries and chimney-stacks, where they collect scraps, secrets and shiny things."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Their own voices are thin and rasping, so they speak the world in borrowed sounds: a door creak, a laugh, a merchant''s cry. A corvid who has heard you once can speak in your voice for years, and the clever ones know exactly why that is useful."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Careful Hand", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on any check you make to copy handwriting or a crafted object that you have seen.\"}]}]}"}, {"name": "Rooftop Training", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You gain proficiency in two of these skills of your choice: Acrobatics, Deception, Stealth or Sleight of Hand.\"}]}]}"}, {"name": "Borrowed Voices", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can reproduce sounds you have heard, including voices. A creature that hears the sounds you make can tell they are imitations with a successful Wisdom (Insight) check against your Charisma (Deception) check.\"}]}]}"}, {"name": "Perfect Recollection", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you make an Intelligence check to recall something you have heard or seen, you can treat a roll of 9 or lower on the d20 as a 10.\"}]}]}"}]'::jsonb, array['Common', 'Primordial']::text[], array['humanoid', 'medium', 'corvid-folk']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'corvid-folk', 'grimoire-species', 'grimoire_2024_corvid-folk', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_lizardfolk', 'Lizardfolk', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lizardfolk are scaled, long-tailed people of marsh and mangrove, with narrow golden eyes, toothy jaws and a stillness that unnerves outsiders. Their villages are built on stilts or hidden in reed beds, and nothing in them is wasted."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They approach the world with practical coldness: a thing matters if it feeds, shelters or protects. This is not cruelty, though outsiders often take it so. They work bone, hide and shell into tools and armour, and share food with a stranger who shows the same respect."}]}]}', 'medium', '{"walk": 30, "swim": 30}'::jsonb, '{"con": 2, "wis": 1}'::jsonb, '[{"name": "Fangs", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your bite is a natural weapon. Your unarmed strikes with it deal 1d6 piercing damage plus your Strength modifier.\"}]}]}"}, {"name": "Marsh Craft", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Magic action, you can work part of a fresh corpse into a club, a shield, darts or javelins, as appropriate to what the animal provided. Making a javelin or dart produces up to four.\"}]}]}"}, {"name": "Long Dive", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can hold your breath for up to 15 minutes.\"}]}]}"}, {"name": "Hunter''s Instinct", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You gain proficiency in two of these skills of your choice: Animal Handling, Nature, Perception, Stealth or Survival.\"}]}]}"}, {"name": "Scaled Hide", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you are not wearing armour, your Armour Class is 13 plus your Dexterity modifier. A shield still works with this.\"}]}]}"}, {"name": "Feeding Bite", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Bonus action, you can make an unarmed bite attack. If it hits, you gain Temporary Hit Points equal to your Proficiency Bonus. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}]'::jsonb, array['Common', 'Draconic']::text[], array['humanoid', 'medium', 'lizardfolk']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'lizardfolk', 'grimoire-species', 'grimoire_2014_lizardfolk', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_lizardfolk', 'Lizardfolk', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lizardfolk are scaled, long-tailed people of marsh and mangrove, with narrow golden eyes, toothy jaws and a stillness that unnerves outsiders. Their villages are built on stilts or hidden in reed beds, and nothing in them is wasted."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They approach the world with practical coldness: a thing matters if it feeds, shelters or protects. This is not cruelty, though outsiders often take it so. They work bone, hide and shell into tools and armour, and share food with a stranger who shows the same respect."}]}]}', 'medium', '{"walk": 30, "swim": 30}'::jsonb, null, '[{"name": "Fangs", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your bite is a natural weapon. Your unarmed strikes with it deal 1d6 piercing damage plus your Strength modifier.\"}]}]}"}, {"name": "Marsh Craft", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Magic action, you can work part of a fresh corpse into a club, a shield, darts or javelins, as appropriate to what the animal provided. Making a javelin or dart produces up to four.\"}]}]}"}, {"name": "Long Dive", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can hold your breath for up to 15 minutes.\"}]}]}"}, {"name": "Hunter''s Instinct", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You gain proficiency in two of these skills of your choice: Animal Handling, Nature, Perception, Stealth or Survival.\"}]}]}"}, {"name": "Scaled Hide", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you are not wearing armour, your Armour Class is 13 plus your Dexterity modifier. A shield still works with this.\"}]}]}"}, {"name": "Feeding Bite", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"As a Bonus action, you can make an unarmed bite attack. If it hits, you gain Temporary Hit Points equal to your Proficiency Bonus. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}]'::jsonb, array['Common', 'Draconic']::text[], array['humanoid', 'medium', 'lizardfolk']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'lizardfolk', 'grimoire-species', 'grimoire_2024_lizardfolk', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_triton', 'Triton', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tritons are blue-green, silver-skinned people with webbed fingers and gill slits along the neck. They have legs rather than tails, so they can walk the shore as easily as the seabed. Their sunken courts are built from coral and wreckage in the cold dark."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They think of themselves as guardians of the deep, holding watch against things that rise from the trenches. They treat surface folk with a polite, wary patience and keep their promises long after anyone else would let go."}]}]}', 'medium', '{"walk": 30, "swim": 30}'::jsonb, '{"str": 1, "con": 1, "cha": 1}'::jsonb, '[{"name": "Two Realms", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can breathe air and water.\"}]}]}"}, {"name": "Cold Water Hide", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to cold damage.\"}]}]}"}, {"name": "Tide Magic", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can cast Fog Cloud once per Long Rest. At 3rd level you can also cast Gust of Wind, and at 5th level Create or Destroy Water, each once per Long Rest. Charisma is your spellcasting ability for them.\"}]}]}"}, {"name": "Speaker to the Sea", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can communicate simple ideas to any animal that lives in water, and you can understand the gist of what they communicate back.\"}]}]}"}]'::jsonb, array['Common', 'Primordial']::text[], array['humanoid', 'medium', 'triton']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'triton', 'grimoire-species', 'grimoire_2014_triton', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_triton', 'Triton', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tritons are blue-green, silver-skinned people with webbed fingers and gill slits along the neck. They have legs rather than tails, so they can walk the shore as easily as the seabed. Their sunken courts are built from coral and wreckage in the cold dark."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They think of themselves as guardians of the deep, holding watch against things that rise from the trenches. They treat surface folk with a polite, wary patience and keep their promises long after anyone else would let go."}]}]}', 'medium', '{"walk": 30, "swim": 30}'::jsonb, null, '[{"name": "Two Realms", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can breathe air and water.\"}]}]}"}, {"name": "Cold Water Hide", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to cold damage.\"}]}]}"}, {"name": "Tide Magic", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can cast Fog Cloud once per Long Rest. At 3rd level you can also cast Gust of Wind, and at 5th level Create or Destroy Water, each once per Long Rest. Charisma is your spellcasting ability for them.\"}]}]}"}, {"name": "Speaker to the Sea", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can communicate simple ideas to any animal that lives in water, and you can understand the gist of what they communicate back.\"}]}]}"}]'::jsonb, array['Common', 'Primordial']::text[], array['humanoid', 'medium', 'triton']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'triton', 'grimoire-species', 'grimoire_2024_triton', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_centaur', 'Centaur', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Centaurs have a humanoid torso joined to the body of a horse. Coat colour runs from dun to black, and the upper half wears whatever hair and expression its owner prefers. They roam wide grasslands in herds, following the grazing and the rains."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They value speed, honest work and a long memory for kin. A centaur camp makes no permanent walls: its borders are the paths its people walk. Visitors are fed and watched, then taught a song, or a pace to keep, before they leave."}]}]}', 'medium', '{"walk": 40}'::jsonb, '{"str": 2, "wis": 1}'::jsonb, '[{"name": "Horse Frame", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You count as one size larger when determining your carrying capacity and the weight you can push, drag or lift. Climbing costs you 4 extra feet of movement for each foot climbed.\"}]}]}"}, {"name": "Hoof Strike", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your hooves are natural weapons. Your unarmed strikes with them deal 1d6 bludgeoning damage plus your Strength modifier.\"}]}]}"}, {"name": "Gathering Rush", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"If you move at least 30 feet in a straight line towards a creature and then hit it with a melee weapon attack in the same turn, you deal an extra 1d6 damage of the weapon''s type. Immediately after this, you can use a Bonus action to make a hoof strike against the same creature.\"}]}]}"}, {"name": "Plains Wisdom", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You gain proficiency in one of these skills of your choice: Animal Handling, Medicine, Nature or Survival.\"}]}]}"}]'::jsonb, array['Common', 'Sylvan']::text[], array['humanoid', 'medium', 'centaur']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'centaur', 'grimoire-species', 'grimoire_2014_centaur', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_centaur', 'Centaur', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Centaurs have a humanoid torso joined to the body of a horse. Coat colour runs from dun to black, and the upper half wears whatever hair and expression its owner prefers. They roam wide grasslands in herds, following the grazing and the rains."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They value speed, honest work and a long memory for kin. A centaur camp makes no permanent walls: its borders are the paths its people walk. Visitors are fed and watched, then taught a song, or a pace to keep, before they leave."}]}]}', 'medium', '{"walk": 40}'::jsonb, null, '[{"name": "Horse Frame", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You count as one size larger when determining your carrying capacity and the weight you can push, drag or lift. Climbing costs you 4 extra feet of movement for each foot climbed.\"}]}]}"}, {"name": "Hoof Strike", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Your hooves are natural weapons. Your unarmed strikes with them deal 1d6 bludgeoning damage plus your Strength modifier.\"}]}]}"}, {"name": "Gathering Rush", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"If you move at least 30 feet in a straight line towards a creature and then hit it with a melee weapon attack in the same turn, you deal an extra 1d6 damage of the weapon''s type. Immediately after this, you can use a Bonus action to make a hoof strike against the same creature.\"}]}]}"}, {"name": "Plains Wisdom", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You gain proficiency in one of these skills of your choice: Animal Handling, Medicine, Nature or Survival.\"}]}]}"}]'::jsonb, array['Common', 'Sylvan']::text[], array['humanoid', 'medium', 'centaur']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'centaur', 'grimoire-species', 'grimoire_2024_centaur', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_satyr', 'Satyr', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Satyrs have curling horns, hairy goat legs and cloven hooves, and an easy way of showing it. They belong to the fey realm''s wilder edges, where feast and song count as a calling, and they are as quick to laugh as they are to take offence."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They like company, wine and a good dance. Among them, a friend is someone who will join the second verse. Under the revelry there is an alert, wary mind that has survived because it was always one step from the nearest exit."}]}]}', 'medium', '{"walk": 35}'::jsonb, '{"cha": 2, "dex": 1}'::jsonb, '[{"name": "Horned Brow", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can make a headbutt as an unarmed strike that deals 1d4 bludgeoning damage plus your Strength modifier.\"}]}]}"}, {"name": "Springing Hooves", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you make a long or high jump, you can roll a d8 and add the result to the number of feet you cover. The extra distance uses up movement as usual.\"}]}]}"}, {"name": "Ward of the Wild", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws against spells and other magical effects.\"}]}]}"}, {"name": "Festival Talents", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have proficiency in the Performance and Persuasion skills, and with one musical instrument of your choice.\"}]}]}"}]'::jsonb, array['Common', 'Sylvan']::text[], array['humanoid', 'medium', 'satyr']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'satyr', 'grimoire-species', 'grimoire_2014_satyr', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_satyr', 'Satyr', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Satyrs have curling horns, hairy goat legs and cloven hooves, and an easy way of showing it. They belong to the fey realm''s wilder edges, where feast and song count as a calling, and they are as quick to laugh as they are to take offence."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They like company, wine and a good dance. Among them, a friend is someone who will join the second verse. Under the revelry there is an alert, wary mind that has survived because it was always one step from the nearest exit."}]}]}', 'medium', '{"walk": 35}'::jsonb, null, '[{"name": "Horned Brow", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can make a headbutt as an unarmed strike that deals 1d4 bludgeoning damage plus your Strength modifier.\"}]}]}"}, {"name": "Springing Hooves", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"When you make a long or high jump, you can roll a d8 and add the result to the number of feet you cover. The extra distance uses up movement as usual.\"}]}]}"}, {"name": "Ward of the Wild", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws against spells and other magical effects.\"}]}]}"}, {"name": "Festival Talents", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have proficiency in the Performance and Persuasion skills, and with one musical instrument of your choice.\"}]}]}"}]'::jsonb, array['Common', 'Sylvan']::text[], array['humanoid', 'medium', 'satyr']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'satyr', 'grimoire-species', 'grimoire_2024_satyr', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_fairy', 'Fairy', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fairies are small, winged adults of the fey, barely taller than a child. Their wings can be butterfly, dragonfly or bat-like, and their skin and hair take colours from flowers, frost or the dusk. They shed faint light when excited or afraid."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Many live in meadows and forest edges where the world feels thin, and they are known for curiosity, mischief and an odd sense of fairness. A fairy owes a favour exactly as heavily as one was given, and no more than that."}]}]}', 'small', '{"walk": 30, "fly": 30}'::jsonb, '{"dex": 2, "cha": 1}'::jsonb, '[{"name": "Gossamer Wings", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have a Fly speed equal to your walking Speed. You cannot fly while wearing medium or heavy armour.\"}]}]}"}, {"name": "Sprite Magic", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You know the Druidcraft cantrip. At 3rd level, you can cast Faerie Fire once per Long Rest, and at 5th level, Enlarge/Reduce once per Long Rest, without spell slots. Intelligence, Wisdom or Charisma (pick one when you choose this species) is your spellcasting ability for these spells.\"}]}]}"}]'::jsonb, array['Common', 'Sylvan']::text[], array['humanoid', 'small', 'fairy']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'fairy', 'grimoire-species', 'grimoire_2014_fairy', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_fairy', 'Fairy', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fairies are small, winged adults of the fey, barely taller than a child. Their wings can be butterfly, dragonfly or bat-like, and their skin and hair take colours from flowers, frost or the dusk. They shed faint light when excited or afraid."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Many live in meadows and forest edges where the world feels thin, and they are known for curiosity, mischief and an odd sense of fairness. A fairy owes a favour exactly as heavily as one was given, and no more than that."}]}]}', 'small', '{"walk": 30, "fly": 30}'::jsonb, null, '[{"name": "Gossamer Wings", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have a Fly speed equal to your walking Speed. You cannot fly while wearing medium or heavy armour.\"}]}]}"}, {"name": "Sprite Magic", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You know the Druidcraft cantrip. At 3rd level, you can cast Faerie Fire once per Long Rest, and at 5th level, Enlarge/Reduce once per Long Rest, without spell slots. Intelligence, Wisdom or Charisma (pick one when you choose this species) is your spellcasting ability for these spells.\"}]}]}"}]'::jsonb, array['Common', 'Sylvan']::text[], array['humanoid', 'small', 'fairy']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'fairy', 'grimoire-species', 'grimoire_2024_fairy', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_starfarer', 'Starfarer', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Starfarers are lean, long-limbed people with pale jade to olive-green skin, ears swept back like blades, and pale eyes that glow faintly in the dark. They keep their hair in tight topknots and carry weapons of faceted violet crystal that hum when drawn."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Their fortresses drift through a starry void far from any shore, and their whole culture is built on drill, rank and the sworn word. A starfarer on the road is a soldier between campaigns, courteous, exact and hard to surprise, with a mind that shifts things without hands."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"int": 2, "str": 1}'::jsonb, '[{"name": "Unseen Fingers", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You know the Mage Hand cantrip, and the hand is invisible when you cast it. Intelligence is your spellcasting ability for it.\"}]}]}"}, {"name": "Void Leap", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"At 3rd level, you can cast Jump once per Long Rest without a spell slot. At 5th level, you can also cast Misty Step once per Long Rest without a spell slot.\"}]}]}"}, {"name": "Drill Discipline", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You gain proficiency with light armour and with one skill or tool of your choice.\"}]}]}"}, {"name": "Steady Thought", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws against the Charmed and Frightened conditions, and you have Resistance to psychic damage.\"}]}]}"}]'::jsonb, array['Common', 'Deep Speech']::text[], array['humanoid', 'medium', 'starfarer']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'starfarer', 'grimoire-species', 'grimoire_2014_starfarer', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_starfarer', 'Starfarer', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Starfarers are lean, long-limbed people with pale jade to olive-green skin, ears swept back like blades, and pale eyes that glow faintly in the dark. They keep their hair in tight topknots and carry weapons of faceted violet crystal that hum when drawn."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Their fortresses drift through a starry void far from any shore, and their whole culture is built on drill, rank and the sworn word. A starfarer on the road is a soldier between campaigns, courteous, exact and hard to surprise, with a mind that shifts things without hands."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Unseen Fingers", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You know the Mage Hand cantrip, and the hand is invisible when you cast it. Intelligence is your spellcasting ability for it.\"}]}]}"}, {"name": "Void Leap", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"At 3rd level, you can cast Jump once per Long Rest without a spell slot. At 5th level, you can also cast Misty Step once per Long Rest without a spell slot.\"}]}]}"}, {"name": "Drill Discipline", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You gain proficiency with light armour and with one skill or tool of your choice.\"}]}]}"}, {"name": "Steady Thought", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws against the Charmed and Frightened conditions, and you have Resistance to psychic damage.\"}]}]}"}]'::jsonb, array['Common', 'Deep Speech']::text[], array['humanoid', 'medium', 'starfarer']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'starfarer', 'grimoire-species', 'grimoire_2024_starfarer', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_stillwarden', 'Stillwarden', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Stillwardens share the Starfarers'' jade-green skin and swept-back ears, but wear plain robes and either shave their heads or keep one long braid. They are slow-spoken people whose eyes seem to rest a moment longer on whatever they look at."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Their monasteries sit in pockets of calm held steady inside raging storms of fire, stone, water and wind, and a Stillwarden carries that calm outward. They prize patience and watchfulness, and are slow to anger and slower to be moved."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"wis": 2, "int": 1}'::jsonb, '[{"name": "Quiet Reach", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You know the Mage Hand cantrip, and the hand is invisible when you cast it. Wisdom is your spellcasting ability for it.\"}]}]}"}, {"name": "Held Breath of Calm", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"At 3rd level, you can cast Shield once per Long Rest without a spell slot. At 5th level, you can also cast Detect Magic once per Long Rest without a spell slot.\"}]}]}"}, {"name": "Settled Spirit", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws against the Charmed and Frightened conditions.\"}]}]}"}, {"name": "Inner Citadel", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to psychic damage. When you take psychic damage or fail a saving throw against a spell that targets your mind, you can use your Reaction to reduce the damage by an amount equal to your Proficiency Bonus, or to gain a +2 bonus to that save before the result is known. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}]'::jsonb, array['Common', 'Deep Speech']::text[], array['humanoid', 'medium', 'stillwarden']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'stillwarden', 'grimoire-species', 'grimoire_2014_stillwarden', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_stillwarden', 'Stillwarden', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Stillwardens share the Starfarers'' jade-green skin and swept-back ears, but wear plain robes and either shave their heads or keep one long braid. They are slow-spoken people whose eyes seem to rest a moment longer on whatever they look at."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Their monasteries sit in pockets of calm held steady inside raging storms of fire, stone, water and wind, and a Stillwarden carries that calm outward. They prize patience and watchfulness, and are slow to anger and slower to be moved."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Quiet Reach", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You know the Mage Hand cantrip, and the hand is invisible when you cast it. Wisdom is your spellcasting ability for it.\"}]}]}"}, {"name": "Held Breath of Calm", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"At 3rd level, you can cast Shield once per Long Rest without a spell slot. At 5th level, you can also cast Detect Magic once per Long Rest without a spell slot.\"}]}]}"}, {"name": "Settled Spirit", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Advantage on saving throws against the Charmed and Frightened conditions.\"}]}]}"}, {"name": "Inner Citadel", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to psychic damage. When you take psychic damage or fail a saving throw against a spell that targets your mind, you can use your Reaction to reduce the damage by an amount equal to your Proficiency Bonus, or to gain a +2 bonus to that save before the result is known. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}]'::jsonb, array['Common', 'Deep Speech']::text[], array['humanoid', 'medium', 'stillwarden']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'stillwarden', 'grimoire-species', 'grimoire_2024_stillwarden', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_serpentkin', 'Serpentkin', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Serpentkin are human-bodied people of snake blood. Some show only slit pupils and a flickering tongue; others bear bands of scale along the arms, a mottled throat, or a ridge down the spine. They stand on two legs and walk quietly, with an unblinking attention that unsettles strangers."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They live in temples swallowed by jungle, where patience, venom-lore and old, quiet cruelty are the household arts. Serpentkin rarely lose their temper, and they do not forget who made them lose it."}]}]}', 'medium', '{"walk": 30}'::jsonb, '{"cha": 2, "con": 1}'::jsonb, '[{"name": "Warm-Stone Sight", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Venom Ward", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to poison damage and Advantage on saving throws against the Poisoned condition.\"}]}]}"}, {"name": "Coiled Will", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can give yourself Advantage on a saving throw against a spell or magical effect. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}, {"name": "Serpent''s Tongue", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You know the Poison Spray cantrip. You can also cast Animal Friendship once per Long Rest without a spell slot, but it can target only snakes. At 3rd level, you can cast Suggestion once per Long Rest without a spell slot. Charisma is your spellcasting ability for these spells.\"}]}]}"}]'::jsonb, array['Common', 'Draconic']::text[], array['humanoid', 'medium', 'serpentkin']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2014', 'serpentkin', 'grimoire-species', 'grimoire_2014_serpentkin', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_2024_serpentkin', 'Serpentkin', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Serpentkin are human-bodied people of snake blood. Some show only slit pupils and a flickering tongue; others bear bands of scale along the arms, a mottled throat, or a ridge down the spine. They stand on two legs and walk quietly, with an unblinking attention that unsettles strangers."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "They live in temples swallowed by jungle, where patience, venom-lore and old, quiet cruelty are the household arts. Serpentkin rarely lose their temper, and they do not forget who made them lose it."}]}]}', 'medium', '{"walk": 30}'::jsonb, null, '[{"name": "Warm-Stone Sight", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 60 feet.\"}]}]}"}, {"name": "Venom Ward", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Resistance to poison damage and Advantage on saving throws against the Poisoned condition.\"}]}]}"}, {"name": "Coiled Will", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You can give yourself Advantage on a saving throw against a spell or magical effect. You can do this a number of times equal to your Proficiency Bonus, regaining all uses after a Long Rest.\"}]}]}"}, {"name": "Serpent''s Tongue", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You know the Poison Spray cantrip. You can also cast Animal Friendship once per Long Rest without a spell slot, but it can target only snakes. At 3rd level, you can cast Suggestion once per Long Rest without a spell slot. Charisma is your spellcasting ability for these spells.\"}]}]}"}]'::jsonb, array['Common', 'Draconic']::text[], array['humanoid', 'medium', 'serpentkin']::text[], null, false, 'grimoire-species', 'Grimoire Species (homebrew)', '2024', 'serpentkin', 'grimoire-species', 'grimoire_2024_serpentkin', 'Dungeon Grimoire homebrew, October 2026', 'grimoire', '{"provider": "grimoire", "document": {"key": "grimoire-species", "publisher": {"key": "grimoire", "name": "Dungeon Grimoire"}}}'::jsonb),
  ('grimoire_owlfolk', 'Owlfolk', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Owlfolk are feathered people with round, watchful eyes and faces shaped like an owl''s, but bodies built much like anyone else''s. They gather where knowledge gathers: libraries in old forests, observatories, the back rooms of scribes'' halls. They keep late hours, speak softly and listen far better than they talk."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Their plumage follows their lineage, from snowy white to barred tawny brown. Long flight feathers line the back of each arm, so a raised arm opens into a broad, silent wing while the hand stays free; most wear coats with open sleeves. An owlfolk who trusts you will share almost anything they know; one who does not will remember everything you said."}]}]}', 'medium', '{"walk": 30, "fly": 30}'::jsonb, '{"dex": 2, "wis": 1}'::jsonb, '[{"name": "Moonlit Eyes", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have Darkvision with a range of 120 feet.\"}]}]}"}, {"name": "Soft Plumage", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have proficiency in the Stealth skill.\"}]}]}"}, {"name": "Hushed Wings", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You have a Fly speed equal to your walking speed. You can''t use this Fly speed while you wear Medium or Heavy armour.\"}]}]}"}, {"name": "Night Learning", "description": "{\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"You know one cantrip of your choice from the Wizard spell list. Intelligence, Wisdom or Charisma is your spellcasting ability for it (choose when you select this species).\"}]}]}"}]'::jsonb, array['Common', 'Sylvan']::text[], a